function y = f2(x)
y = 1 - x .* exp(-x);
end

x = 0:0.01:2;
y = sinh(x);
z = tanh(x);
plot(x,y,x,z,'--');
xlabel('x');
ylabel('Hyperbolic sine and tangent');
legend('sinh(x)','tanh(x)');

if x >= 5
    y = log(x);
elseif x >= 0
    y = sqrt(x);
else
    y = exp(x) - 1;
end

for k = 1:21
    x = (k-1)*5;
    y(k) = cos(x);
end

x = 5;
while x < 25
    disp(x)
    x = 2*x - 1;
end
